'use strict';

function makeTitle(raw) {
  var words = raw.split(' ');
  var out = [];
  for (var i = 0; i < words.length; i++) {
    var w = words[i];
    out.push(w.charAt(0).toUpperCase() + w.slice(1));
  }
  return '## ' + out.join(' ');
}

function makeLabel(raw) {
  var words = raw.split(' ');
  var out = [];
  for (var i = 0; i < words.length; i++) {
    var w = words[i];
    out.push(w.charAt(0).toUpperCase() + w.slice(1));
  }
  return '[' + out.join(' ') + ']';
}

module.exports = { makeTitle: makeTitle, makeLabel: makeLabel };

