const test = require('node:test');
const assert = require('node:assert');
const report = require('../src/report.js');

test('capitalizeWords is exported and works', () => {
  assert.strictEqual(typeof report.capitalizeWords, 'function');
  assert.strictEqual(report.capitalizeWords('weekly sales'), 'Weekly Sales');
});

test('existing outputs are unchanged', () => {
  assert.strictEqual(report.makeTitle('weekly sales'), '## Weekly Sales');
  assert.strictEqual(report.makeLabel('q3 numbers'), '[Q3 Numbers]');
});

test('surprising but correct edge cases are preserved', () => {
  // split(' ') keeps empty words, so runs of spaces survive untouched
  assert.strictEqual(report.capitalizeWords('a  b'), 'A  B');
  // charAt(0)/slice(1) never lowercases the tail: 'iOS' becomes 'IOS'
  assert.strictEqual(report.capitalizeWords('iOS release'), 'IOS Release');
});

test('the duplicated loop was actually extracted, not just wrapped', () => {
  const src = require('node:fs').readFileSync(require.resolve('../src/report.js'), 'utf8');
  const copies = src.split('toUpperCase').length - 1;
  assert.ok(copies <= 1, 'capitalize logic should live in one place, found ' + copies + ' copies');
});

