'use strict';

function capitalizeWords(raw) {
  var words = raw.split(' ');
  var out = [];
  for (var i = 0; i < words.length; i++) {
    var w = words[i];
    out.push(w.charAt(0).toUpperCase() + w.slice(1));
  }
  return out.join(' ');
}

function makeTitle(raw) {
  return '## ' + capitalizeWords(raw);
}

function makeLabel(raw) {
  return '[' + capitalizeWords(raw) + ']';
}

module.exports = { makeTitle: makeTitle, makeLabel: makeLabel, capitalizeWords: capitalizeWords };
